-- Test Paper Questions with bank_question_id linkage
INSERT INTO public.questions (
  question_id, mock_test_id, subject_id, bank_question_id,
  question_text, question_type, marks_per_question, negative_marking,
  option_array, answers, question_image_url
)
VALUES
  ('10000000-0000-4000-8000-000000000001', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000001', 'Let $\alpha, \alpha+2$, $\alpha \in \mathbb{Z}$, be the roots of the quadratic equation $x(x+2)+(x+1)(x+3)+(x+2)(x+4)+\dots+(x+n-1)(x+n+1)=40n$ for some $n \in \mathbb{N}$. Then $n+\alpha$ is equal to:', 'MCQ', 4, 1, '[{"key":"A","text":"0"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"3"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000002', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000002', 'Let $x$ and $y$ be real numbers such that $50\left(\frac{2x}{1+3i}-\frac{y}{1-2i}\right)=31+17i$, $i=\sqrt{-1}$. Then the value of $10(x-3y)$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"20"},{"key":"B","text":"31"},{"key":"C","text":"35"},{"key":"D","text":"75"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000003', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000003', 'Let $\alpha,\beta \in \mathbb{R}$ be such that the system of linear equations:
$x+2y+z=5$
$2x+y+\alpha z=5$
$8x+4y+\beta z=18$
has no solution. Then $\frac{\beta}{\alpha}$ is equal to:', 'MCQ', 4, 1, '[{"key":"A","text":"-4"},{"key":"B","text":"4"},{"key":"C","text":"8"},{"key":"D","text":"-8"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000004', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000004', 'Let $A=\begin{bmatrix}1&2\\ 1&\alpha\end{bmatrix}$ and $B=\begin{bmatrix}3&3\\ \beta&2\end{bmatrix}$. If $A^2-4A+I=O$ and $B^2-5B-6I=O$, then among the two statements:
(S1): $[(B-A)(B+A)]^T=\begin{bmatrix}13&15\\ 7&10\end{bmatrix}$
(S2): $\det(\text{adj}(A+B))=-5$:', 'MCQ', 4, 1, '[{"key":"A","text":"only (S1) is correct"},{"key":"B","text":"only (S2) is correct"},{"key":"C","text":"both (S1) and (S2) are correct"},{"key":"D","text":"both (S1) and (S2) are wrong"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000005', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000005', 'Let A be the set of first 101 terms of an A.P., whose first term is 1 and the common difference is 5 and let B be the set of first 71 terms of an A.P., whose first term is 9 and the common difference is 7. Then the number of elements in $A \cap B$, which are divisible by 3, is:', 'MCQ', 4, 1, '[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"7"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000006', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000006', 'The number of seven-digit numbers, that can be formed by using the digits 1, 2, 3, 5 and 7 such that each digit is used at least once, is:', 'MCQ', 4, 1, '[{"key":"A","text":"15400"},{"key":"B","text":"17800"},{"key":"C","text":"16800"},{"key":"D","text":"29400"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000007', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000007', 'The number of elements in the set $S=\left\{(r,k): k \in \mathbb{Z} \text{ and } {}^{36}C_{r+1} = \frac{6({}^{35}C_r)}{k^2-3}\right\}$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"2"},{"key":"B","text":"4"},{"key":"C","text":"8"},{"key":"D","text":"16"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000008', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000008', 'If the mean of the data:
Class: 5-10 | 10-15 | 15-20 | 20-25 | 25-30 | 30-35
Frequency: 2 | k | 28 | 54 | k+1 | 5
is 21, then k is one of the roots of the equation:', 'MCQ', 4, 1, '[{"key":"A","text":"$2x^2-23x-10=0$"},{"key":"B","text":"$4x^2-35x+24=0$"},{"key":"C","text":"$2x^2-19x-10=0$"},{"key":"D","text":"$2x^2-35x+98=0$"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000009', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000009', 'Let the mid points of the sides of a triangle ABC be $(\frac{5}{2},7)$, $(\frac{5}{2},3)$ and $(4,5)$. If its incentre is $(h, k)$, then $3h+k$ is equal to:', 'MCQ', 4, 1, '[{"key":"A","text":"11"},{"key":"B","text":"12"},{"key":"C","text":"13"},{"key":"D","text":"14"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000010', 'f0000000-0000-4000-8000-000000000001', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000010', 'Let an ellipse $\frac{x^2}{a^2}+\frac{y^2}{b^2}=1$, $a<b$, pass through the point $(4,3)$ and have eccentricity $\frac{\sqrt{5}}{3}$. Then the length of its latus rectum is:', 'MCQ', 4, 1, '[{"key":"A","text":"$\\frac{4\\sqrt{5}}{3}$"},{"key":"B","text":"$2\\sqrt{5}$"},{"key":"C","text":"$\\frac{7\\sqrt{5}}{3}$"},{"key":"D","text":"$\\frac{8\\sqrt{5}}{3}$"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000011', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000008', 'If the mean of the data:
Class: 5-10 | 10-15 | 15-20 | 20-25 | 25-30 | 30-35
Frequency: 2 | k | 28 | 54 | k+1 | 5
is 21, then k is one of the roots of the equation:', 'MCQ', 4, 1, '[{"key":"A","text":"$2x^2-23x-10=0$"},{"key":"B","text":"$4x^2-35x+24=0$"},{"key":"C","text":"$2x^2-19x-10=0$"},{"key":"D","text":"$2x^2-35x+98=0$"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000012', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000009', 'Let the mid points of the sides of a triangle ABC be $(\frac{5}{2},7)$, $(\frac{5}{2},3)$ and $(4,5)$. If its incentre is $(h, k)$, then $3h+k$ is equal to:', 'MCQ', 4, 1, '[{"key":"A","text":"11"},{"key":"B","text":"12"},{"key":"C","text":"13"},{"key":"D","text":"14"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000013', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000010', 'Let an ellipse $\frac{x^2}{a^2}+\frac{y^2}{b^2}=1$, $a<b$, pass through the point $(4,3)$ and have eccentricity $\frac{\sqrt{5}}{3}$. Then the length of its latus rectum is:', 'MCQ', 4, 1, '[{"key":"A","text":"$\\frac{4\\sqrt{5}}{3}$"},{"key":"B","text":"$2\\sqrt{5}$"},{"key":"C","text":"$\\frac{7\\sqrt{5}}{3}$"},{"key":"D","text":"$\\frac{8\\sqrt{5}}{3}$"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000014', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000011', 'If $\sin\left(\frac{\pi}{18}\right)\sin\left(\frac{5\pi}{18}\right)\sin\left(\frac{7\pi}{18}\right)=K$, then the value of $\sin\left(\frac{10K\pi}{3}\right)$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"$\\frac{\\sqrt{3}+1}{2\\sqrt{2}}$"},{"key":"B","text":"$\\frac{\\sqrt{3}-1}{\\sqrt{2}}$"},{"key":"C","text":"$\\frac{\\sqrt{3}}{2}$"},{"key":"D","text":"$\\frac{1}{2}$"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000015', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000012', 'Let $S=\{x \in [-\pi,\pi]: \sin x(\sin x+\cos x)=a, a \in \mathbb{Z}\}$. Then $n(S)$ is equal to:', 'MCQ', 4, 1, '[{"key":"A","text":"3"},{"key":"B","text":"6"},{"key":"C","text":"7"},{"key":"D","text":"9"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000016', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000013', 'If the point of intersection of the lines $\frac{x+1}{3}=\frac{y+a}{5}=\frac{z+b+1}{7}$ and $\frac{x-2}{1}=\frac{y-b}{4}=\frac{z-2a}{7}$ lies on xy-plane, then the value of $a+b$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"2"},{"key":"B","text":"5"},{"key":"C","text":"7"},{"key":"D","text":"9"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000017', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000014', 'If $\vec{a}$ and $\vec{b}$ are two vectors such that $|\vec{a}|=2$ and $|\vec{b}|=3$, then the maximum value of $3|(3\vec{a}+2\vec{b})|+4|(3\vec{a}-2\vec{b})|$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"30"},{"key":"B","text":"36"},{"key":"C","text":"60"},{"key":"D","text":"72"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000018', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000015', 'Let a line L passing through the point $(1, 1, 1)$ be perpendicular to both the vectors $2\hat{i}+2\hat{j}+\hat{k}$ and $\hat{i}+2\hat{j}+2\hat{k}$. If $P(a,b,c)$ is the foot of perpendicular from the origin on the line L, then the value of $34(a+b+c)$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"50"},{"key":"B","text":"80"},{"key":"C","text":"100"},{"key":"D","text":"120"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000019', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000016', 'If $\lim_{x\rightarrow 2}\frac{\sin(x^3-5x^2+ax+b)}{(\sqrt{x-1}-1)\log_e(x-1)}=m$, then $a+b+m$ is equal to:', 'MCQ', 4, 1, '[{"key":"A","text":"5"},{"key":"B","text":"6"},{"key":"C","text":"8"},{"key":"D","text":"10"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000020', 'f0000000-0000-4000-8000-000000000002', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000017', 'If the curve $y=f(x)$ passes through the point $(1, e)$ and satisfies the differential equation $dy=y(2+\log_e x)dx$, $x>0$, then $f(e)$ is equal to:', 'MCQ', 4, 1, '[{"key":"A","text":"$e$"},{"key":"B","text":"$e^{e^2}$"},{"key":"C","text":"$e^{2e}$"},{"key":"D","text":"$e^{3e}$"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000021', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000040', 'For a thin symmetric prism made of glass (refractive index 1.5), the ratio of incident angle and minimum deviation will be:', 'MCQ', 4, 1, '[{"key":"A","text":"3:4"},{"key":"B","text":"3:2"},{"key":"C","text":"2:1"},{"key":"D","text":"1:2"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000022', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000041', 'Refer the figure given below. $\mu_1$ and $\mu_2$ are refractive indices of air and lens material. The height of image will be ___ cm.', 'MCQ', 4, 1, '[{"key":"A","text":"1"},{"key":"B","text":"0.5"},{"key":"C","text":"1.2"},{"key":"D","text":"0.25"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, '/diagrams/q41_refraction_curved_surface.png'),
  ('10000000-0000-4000-8000-000000000023', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000042', 'For a certain metal, when monochromatic light of wavelength $\lambda$ is incident, the stopping potential for photoelectrons is $3V_0$. When the same metal is illuminated by light of wavelength $2\lambda$, then the stopping potential becomes $V_0$. The threshold wavelength for photoelectric emission for the given metal is $\alpha\lambda$. The value of $\alpha$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"1"},{"key":"B","text":"4"},{"key":"C","text":"2"},{"key":"D","text":"3"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000024', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000043', 'An electromagnetic wave travelling in x-direction is described by field equation $E_y=300\sin\omega\left(t-\frac{x}{c}\right)$. If the electron is restricted to move in y-direction only with speed of $1.5\times10^{6}\text{ m/s}$, then ratio of maximum electric and magnetic forces acting on the electron is:', 'MCQ', 4, 1, '[{"key":"A","text":"200"},{"key":"B","text":"150"},{"key":"C","text":"400"},{"key":"D","text":"300"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000025', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000044', 'Angular momentum of an electron in a hydrogen atom is $\frac{3h}{\pi}$, then the energy of the electron is ___ eV.', 'MCQ', 4, 1, '[{"key":"A","text":"-1.51"},{"key":"B","text":"-0.85"},{"key":"C","text":"-0.38"},{"key":"D","text":"-0.28"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000026', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000045', 'A liquid drop of diameter 2 mm breaks into 512 droplets. The change in surface energy is $\alpha\times10^{-6}\text{ J}$. The value of $\alpha$ is (Take surface tension of liquid $=0.08\text{ N/m}$):', 'MCQ', 4, 1, '[{"key":"A","text":"10"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"11"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000027', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000046', 'In single slit diffraction pattern, the wavelength of light used is 628 nm and slit width is 0.2 mm, the angular width of central maximum is $\alpha\times10^{-2}$ degrees. The value of $\alpha$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"36","key":"36"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000028', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000047', 'A vessel contains $0.15\text{ m}^3$ of a gas at pressure 8 bar and temperature $140^{\circ}\text{C}$ with $c_p=3R$ and $c_v=2R$. It is expanded adiabatically till pressure falls to 1 bar. The work done during this process is ___ kJ. (R is gas constant)', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"120","key":"120"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000029', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000048', 'A $1\ \mu\text{C}$ charge is moving with velocity $\vec{v}=(\hat{i}-2\hat{j}+3\hat{k})\text{ m/s}$ in the region of magnetic field $\vec{B}=(2\hat{i}+3\hat{j}-5\hat{k})\text{ T}$. The magnitude of force acting on it is $\sqrt{\alpha}\times10^{-6}\text{ N}$. The value of $\alpha$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"171","key":"171"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000030', 'f0000000-0000-4000-8000-000000000003', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000049', 'A uniform wire of length $l$ of weight $w$ is suspended from the roof with a weight of $W$ at the other end. The stress in the wire at $\frac{l}{3}$ distance from the top is $\left(\frac{W}{A}+\frac{2}{\gamma}\frac{w}{A}\right)$, where A is the cross sectional area of the wire. The value of $\gamma$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000031', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000072', 'Consider the isomers of hydrocarbon with molecular formula $\text{C}_5\text{H}_{10}$. These isomers do not decolourise $\text{KMnO}_4$ solution. These isomers are subjected to chlorination with chlorine in presence of light to give monochloro compounds. The total number of monochloro compounds (structural isomers only) formed is:', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"14","key":"14"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000032', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000073', 'One mole of an alkane (x) requires 8 mole oxygen for complete combustion. Sum of number of carbon and hydrogen atoms in the alkane (x) is:', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"17","key":"17"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000033', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000074', 'For reaction $A\rightarrow P$ rate constant $k=1.5\times10^3\text{ s}^{-1}$ at $27^{\circ}\text{C}$. If activation energy for the above reaction is $60\text{ kJ mol}^{-1}$, then the temperature (in $^{\circ}\text{C}$) at which rate constant $k=4.5\times10^3\text{ s}^{-1}$ is ___ (Nearest integer)
Given: $\log 2=0.30, \log 3=0.48, R = 8.3\text{ J K}^{-1}\text{mol}^{-1}, \ln 10=2.3$', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"41","key":"41"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000034', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000075', 'At the transition temperature T, $A\rightleftharpoons B$ and $\Delta G^0=105-35\log T$ where A and B are two states of substance X. The transition temperature in $^{\circ}\text{C}$ when pressure is 1 atm is ___ (Nearest integer)', 'MCQ', 4, 1, '[{"key":"A","text":"Option A"},{"key":"B","text":"Option B"},{"key":"C","text":"Option C"},{"key":"D","text":"Option D"}]'::jsonb, '{"correct":"727","key":"727"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000035', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000078', '[Q78] The basicity of orthophosphoric acid ($\text{H}_3\text{PO}_4$) is:', 'MCQ', 4, 1, '[{"key":"A","text":"$2$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$4$"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000036', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000081', '[Q81] Standard electrode potential $E^\circ$ for $\text{Zn}^{2+}/\text{Zn}$ is $-0.76$ V and for $\text{Cu}^{2+}/\text{Cu}$ is $+0.34$ V. The cell EMF $E^\circ_{\text{cell}}$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"$-1.10$ V"},{"key":"B","text":"$+0.42$ V"},{"key":"C","text":"$-0.42$ V"},{"key":"D","text":"$+1.10$ V"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000037', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000084', '[Q84] The van ''t Hoff factor $i$ for a dilute aqueous solution of barium chloride $\text{BaCl}_2$ assuming complete dissociation is:', 'MCQ', 4, 1, '[{"key":"A","text":"$3$"},{"key":"B","text":"$2$"},{"key":"C","text":"$1$"},{"key":"D","text":"$4$"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000038', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000087', '[Q87] Which of the following nitrogenous bases is found in RNA but not in DNA?', 'MCQ', 4, 1, '[{"key":"A","text":"Thymine"},{"key":"B","text":"Uracil"},{"key":"C","text":"Guanine"},{"key":"D","text":"Cytosine"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000039', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000090', '[Q90] The hybridization and magnetic character of $[\text{Ni}(\text{CN})_4]^{2-}$ complex ion are:', 'MCQ', 4, 1, '[{"key":"A","text":"$sp^3$, Paramagnetic"},{"key":"B","text":"$dsp^2$, Paramagnetic"},{"key":"C","text":"$dsp^2$, Diamagnetic"},{"key":"D","text":"$sp^3$, Diamagnetic"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000040', 'f0000000-0000-4000-8000-000000000004', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000093', '[Q93] For an endothermic reaction to be spontaneous at all temperatures, the change in entropy $\Delta S$ must be:', 'MCQ', 4, 1, '[{"key":"A","text":"Negative"},{"key":"B","text":"Zero"},{"key":"C","text":"Always non-spontaneous"},{"key":"D","text":"Positive and $T\\Delta S > \\Delta H$"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000041', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000029', 'The position of an object having mass 0.1 kg as a function of time t is given as $\vec{r}=(10t^2\hat{i}+5t^3\hat{j})\text{ m}$. At $t=1\text{ s}$, which of the following statements are correct?
A. The linear momentum $\vec{p}=(2\hat{i}+1.5\hat{j})\text{ kg}\cdot\text{m/s}$.
B. The force acting on the object $\vec{F}=(2\hat{i}+3\hat{j})\text{ N}$.
C. The angular momentum of the object about its origin $\vec{L}=15\hat{k}\text{ J}\cdot\text{s}$.
D. The torque acting on the object about its origin $\vec{\tau}=20\hat{k}\text{ N}\cdot\text{m}$.
Choose the correct answer from the options given below:', 'MCQ', 4, 1, '[{"key":"A","text":"A, B and C only"},{"key":"B","text":"B, C and D only"},{"key":"C","text":"A, C and D only"},{"key":"D","text":"A, B and D only"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000042', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000030', 'A planet ($P_1$) is moving around the star of mass $2M$ in the orbit of radius $R$. Another planet ($P_2$) is moving around another star of mass $4M$ in an orbit of radius $2R$. Ratio of time periods of revolution of $P_2$ and $P_1$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"$\\frac{1}{2}$"},{"key":"B","text":"2"},{"key":"C","text":"4"},{"key":"D","text":"$\\frac{1}{4}$"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000043', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000031', 'A particle is rotating in a circular path and at any instant its motion can be described as $\theta=\frac{5t^4}{40}-\frac{t^3}{3}$. The angular acceleration of the particle after 10 seconds is ___ $\text{rad/s}^2$:', 'MCQ', 4, 1, '[{"key":"A","text":"150"},{"key":"B","text":"120"},{"key":"C","text":"130"},{"key":"D","text":"170"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000044', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000032', 'A parallel plate air capacitor has a capacitance C. When it is half filled as shown in figure with a dielectric constant $K=5$, the percentage increase in the capacitance is:', 'MCQ', 4, 1, '[{"key":"A","text":"33.34"},{"key":"B","text":"66.67"},{"key":"C","text":"200"},{"key":"D","text":"400"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, '/diagrams/q32_capacitor_dielectric.png'),
  ('10000000-0000-4000-8000-000000000045', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000033', 'Heat is supplied to a diatomic gas at constant pressure. Then the ratio of $\Delta Q:\Delta U:\Delta W$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"2:3:5"},{"key":"B","text":"5:3:2"},{"key":"C","text":"2:5:7"},{"key":"D","text":"7:5:2"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000046', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000034', 'Two charged conducting spheres $S_1$ and $S_2$ of radii 8 cm and 18 cm are connected to each other by a wire. After equilibrium is established, the ratio of electric fields on $S_1$ and $S_2$ spheres are $E_{S_1}$ and $E_{S_2}$ respectively. The value of $\frac{E_{S_1}}{E_{S_2}}$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"$\\frac{3}{2}$"},{"key":"B","text":"$\\frac{2}{3}$"},{"key":"C","text":"$\\frac{4}{9}$"},{"key":"D","text":"$\\frac{9}{4}$"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000047', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000035', 'The equation of a plane progressive wave is given by $y=5\cos\pi\left(200t-\frac{x}{150}\right)$, where $x$ and $y$ are in cm and $t$ is in second. The velocity of the wave is ___ $\text{m/s}$:', 'MCQ', 4, 1, '[{"key":"A","text":"120"},{"key":"B","text":"150"},{"key":"C","text":"200"},{"key":"D","text":"300"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000048', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000036', 'Two short electric dipoles A and B having dipole moment $p_1$ and $p_2$ respectively are placed with their axis mutually perpendicular as shown in the figure. The resultant electric field at a point z is making an angle of $60^{\circ}$ with the line joining points O and z. The ratio of the dipole moments $p_2/p_1$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"$\\frac{\\sqrt{3}}{2}$"},{"key":"B","text":"$2\\sqrt{3}$"},{"key":"C","text":"$\\frac{1}{\\sqrt{3}}$"},{"key":"D","text":"$\\sqrt{3}$"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, '/diagrams/q36_dipoles.png'),
  ('10000000-0000-4000-8000-000000000049', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000037', 'For the given circuit (shown in part (A)) the time dependent input voltage $v_{in}(t)$ and corresponding output $v_o(t)$ are shown in part (B) and part (C), respectively. Identify the components that are used in the circuit between points X and Y.', 'MCQ', 4, 1, '[{"key":"A","text":"Series Resistor connected to terminal Y"},{"key":"B","text":"Parallel Diode and Inductor"},{"key":"C","text":"Single Zener Diode with opposite polarity"},{"key":"D","text":"Series Resistor and opposite back-to-back Zener network"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, '/diagrams/q37_zener_circuit.png'),
  ('10000000-0000-4000-8000-000000000050', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000038', 'When a coil is placed in a time dependent magnetic field the power dissipated in it is P. The number of turns, area of the coil and radius of the coil wire are N, A and r respectively. For a second coil, number of turns, area of the coil and radius of the coil wire are 2N, 2A and 3r respectively. When the first coil is replaced with second coil the power dissipated in it is $\sqrt{2}\alpha P$. The value of $\alpha$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"36"},{"key":"B","text":"$128\\sqrt{2}$"},{"key":"C","text":"16"},{"key":"D","text":"64"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000051', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000039', 'Two identical long current carrying wires are bent into the shapes shown in the following figures. If the magnitude of magnetic fields at the centres P and Q of a semicircular arc are $B_1$ and $B_2$ respectively, then the ratio $\frac{B_1}{B_2}$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"$\\frac{2+\\pi}{1+\\pi}$"},{"key":"B","text":"$\\frac{1+\\pi}{1-\\pi}$"},{"key":"C","text":"$\\frac{2+\\pi}{1-\\pi}$"},{"key":"D","text":"$\\frac{1+\\pi}{2-\\pi}$"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, '/diagrams/q39_wire_loops.png'),
  ('10000000-0000-4000-8000-000000000052', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000040', 'For a thin symmetric prism made of glass (refractive index 1.5), the ratio of incident angle and minimum deviation will be:', 'MCQ', 4, 1, '[{"key":"A","text":"3:4"},{"key":"B","text":"3:2"},{"key":"C","text":"2:1"},{"key":"D","text":"1:2"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000053', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000041', 'Refer the figure given below. $\mu_1$ and $\mu_2$ are refractive indices of air and lens material. The height of image will be ___ cm.', 'MCQ', 4, 1, '[{"key":"A","text":"1"},{"key":"B","text":"0.5"},{"key":"C","text":"1.2"},{"key":"D","text":"0.25"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, '/diagrams/q41_refraction_curved_surface.png'),
  ('10000000-0000-4000-8000-000000000054', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000042', 'For a certain metal, when monochromatic light of wavelength $\lambda$ is incident, the stopping potential for photoelectrons is $3V_0$. When the same metal is illuminated by light of wavelength $2\lambda$, then the stopping potential becomes $V_0$. The threshold wavelength for photoelectric emission for the given metal is $\alpha\lambda$. The value of $\alpha$ is:', 'MCQ', 4, 1, '[{"key":"A","text":"1"},{"key":"B","text":"4"},{"key":"C","text":"2"},{"key":"D","text":"3"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000055', 'f0000000-0000-4000-8000-000000000005', '58aeea98-85ee-4405-9225-57a9bf025aec', 'e0000000-0000-4000-8000-000000000043', 'An electromagnetic wave travelling in x-direction is described by field equation $E_y=300\sin\omega\left(t-\frac{x}{c}\right)$. If the electron is restricted to move in y-direction only with speed of $1.5\times10^{6}\text{ m/s}$, then ratio of maximum electric and magnetic forces acting on the electron is:', 'MCQ', 4, 1, '[{"key":"A","text":"200"},{"key":"B","text":"150"},{"key":"C","text":"400"},{"key":"D","text":"300"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000056', 'f0000000-0000-4000-8000-000000000006', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000106', '[Q106] Let $\vec{a} = 2\hat{i} + \hat{j} - 2\hat{k}$ and $\vec{b} = \hat{i} + \hat{j}$. The projection of $\vec{a}$ along $\vec{b}$ is:', 'MCQ', 4, 0, '[{"key":"A","text":"$\\frac{3}{2}$"},{"key":"B","text":"$\\sqrt{2}$"},{"key":"C","text":"$\\frac{3}{\\sqrt{2}}$"},{"key":"D","text":"$3\\sqrt{2}$"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000057', 'f0000000-0000-4000-8000-000000000006', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000109', '[Q109] Evaluate: $\lim_{x \to 0} \frac{e^{\sin x} - 1 - \sin x}{x^2}$.', 'MCQ', 4, 0, '[{"key":"A","text":"$1$"},{"key":"B","text":"$0$"},{"key":"C","text":"$\\frac{1}{4}$"},{"key":"D","text":"$\\frac{1}{2}$"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000058', 'f0000000-0000-4000-8000-000000000006', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000112', '[Q112] Evaluate the definite integral: $I = \int_{0}^{\pi/2} \frac{\sin^3 x}{\sin^3 x + \cos^3 x} dx$', 'MCQ', 4, 0, '[{"key":"A","text":"$\\frac{\\pi}{4}$"},{"key":"B","text":"$\\frac{\\pi}{2}$"},{"key":"C","text":"$\\pi$"},{"key":"D","text":"$0$"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000059', 'f0000000-0000-4000-8000-000000000006', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000115', '[Q115] The general solution of the differential equation $\frac{dy}{dx} + y \tan x = \sec x$ is:', 'MCQ', 4, 0, '[{"key":"A","text":"$y \\cos x = \\sin x + C$"},{"key":"B","text":"$y \\sec x = \\tan x + C$"},{"key":"C","text":"$y = \\sin x + C \\cos x$"},{"key":"D","text":"$y = \\tan x + C \\sec x$"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000060', 'f0000000-0000-4000-8000-000000000006', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000118', '[Q118] The distance of the point $(1, 2, 3)$ from the plane $2x + y - 2z + 9 = 0$ is:', 'MCQ', 4, 0, '[{"key":"A","text":"$2$"},{"key":"B","text":"$7$"},{"key":"C","text":"$3$"},{"key":"D","text":"$1$"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000061', 'f0000000-0000-4000-8000-000000000006', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000121', '[Q121] If $A$ is a $3 \times 3$ non-singular matrix such that $|A| = 4$, then find the value of $|\text{adj}(2A)|$.', 'MCQ', 4, 0, '[{"key":"A","text":"1024"},{"key":"B","text":"2048"},{"key":"C","text":"512"},{"key":"D","text":"4096"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000062', 'f0000000-0000-4000-8000-000000000006', '50a02b50-667d-4beb-add5-a05a11204e9a', 'e0000000-0000-4000-8000-000000000124', '[Q124] Two dice are thrown simultaneously. The probability that the sum of the numbers appearing on the dice is a prime number is:', 'MCQ', 4, 0, '[{"key":"A","text":"$\\frac{5}{12}$"},{"key":"B","text":"$\\frac{7}{18}$"},{"key":"C","text":"$\\frac{1}{3}$"},{"key":"D","text":"$\\frac{1}{2}$"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
