  ('10000000-0000-4000-8000-000000000076', 'f0000000-0000-4000-8000-000000000008', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000150', '[Q150] The basicity of orthophosphoric acid ($\text{H}_3\text{PO}_4$) is:', 'MCQ', 4, 0, '[{"key":"A","text":"$2$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$4$"}]'::jsonb, '{"correct":"C","key":"C"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000077', 'f0000000-0000-4000-8000-000000000008', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000153', '[Q153] Standard electrode potential $E^\circ$ for $\text{Zn}^{2+}/\text{Zn}$ is $-0.76$ V and for $\text{Cu}^{2+}/\text{Cu}$ is $+0.34$ V. The cell EMF $E^\circ_{\text{cell}}$ is:', 'MCQ', 4, 0, '[{"key":"A","text":"$-1.10$ V"},{"key":"B","text":"$+0.42$ V"},{"key":"C","text":"$-0.42$ V"},{"key":"D","text":"$+1.10$ V"}]'::jsonb, '{"correct":"D","key":"D"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000078', 'f0000000-0000-4000-8000-000000000008', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000156', '[Q156] The van ''t Hoff factor $i$ for a dilute aqueous solution of barium chloride $\text{BaCl}_2$ assuming complete dissociation is:', 'MCQ', 4, 0, '[{"key":"A","text":"$3$"},{"key":"B","text":"$2$"},{"key":"C","text":"$1$"},{"key":"D","text":"$4$"}]'::jsonb, '{"correct":"A","key":"A"}'::jsonb, NULL),
  ('10000000-0000-4000-8000-000000000079', 'f0000000-0000-4000-8000-000000000008', 'd7e1c77a-3837-4f8a-a673-5c852bd356ab', 'e0000000-0000-4000-8000-000000000159', '[Q159] Which of the following nitrogenous bases is found in RNA but not in DNA?', 'MCQ', 4, 0, '[{"key":"A","text":"Thymine"},{"key":"B","text":"Uracil"},{"key":"C","text":"Guanine"},{"key":"D","text":"Cytosine"}]'::jsonb, '{"correct":"B","key":"B"}'::jsonb, NULL),
